import{_ as b,C as d,c as m,o,j as u,G as a,a8 as t,b as s,a as l,w as i,a9 as r}from"./chunks/framework.8HQ-OgOa.js";const I=JSON.parse('{"title":"Toolbar API","description":"Toolbar API","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Toolbar API","description":"Toolbar API"},"headers":[],"relativePath":"en/dev/api-reference/toolbar-api.md","filePath":"en/dev/api-reference/toolbar-api.md"}'),g={name:"en/dev/api-reference/toolbar-api.md"};function p(f,e,h,T,y,A){const c=d("ArticleMetadata"),n=d("Mermaid");return o(),m("div",null,[e[5]||(e[5]=u("h1",{id:"toolbar-api",tabindex:"-1"},[l("Toolbar API "),u("a",{class:"header-anchor",href:"#toolbar-api","aria-label":'Permalink to "Toolbar API"'},"​")],-1)),a(c),e[6]||(e[6]=t('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document systematically outlines and explains the design and implementation of the Toolbar API, covering:</p><ul><li>Design specifications of the IToolbarItem interface: property definitions, event handling mechanisms, and state management methods.</li><li>Toolbar building workflows, layout algorithms, and interaction logics of the ToolbarHost class.</li><li>ToolbarRegistry&#39;s toolbar item registration mechanisms, configuration management, and dynamic loading.</li><li>IToolbarHost interface service capabilities: adding, removing, and sorting toolbar items.</li><li>Toolbar customization guides: how to create custom toolbar items, configure layouts, and handle user interactions.</li><li>Toolbar configuration file formats, serialization mechanisms, and persistence strategies.</li><li>Best practices for toolbar expansions and performance optimization suggestions.</li></ul><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>Toolbar-related code is primarily located in Ink Canvas/Controls/Toolbar and its subdirectories, cooperating with the settings pages and main window initialization workflows.</p>',5)),(o(),s(r,null,{default:i(()=>[a(n,{id:"mermaid-52",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Toolbar%20Control%20Layer%22%0AITI%5B%22IToolbarItem%20Interface%22%5D%0ATHost%5B%22ToolbarHost%20Implementation%22%5D%0ATR%5B%22ToolbarRegistry%20Registration%20and%20Layout%22%5D%0ATIC%5B%22ToolbarItemConfig%20Configuration%20Model%22%5D%0Aend%0Asubgraph%20%22Toolbar%20Item%20Implementation%22%0ABase%5B%22ToolbarImageButtonItemBase%20Abstract%20Base%20Class%22%5D%0ACursor%5B%22CursorToolItem%22%5D%0APen%5B%22PenToolItem%22%5D%0ASep%5B%22SeparatorToolItem%22%5D%0Aend%0Asubgraph%20%22Settings%20and%20Host%22%0ATP%5B%22ToolbarPage%20Settings%20Page%22%5D%0AMW%5B%22MainWindow%20Initialization%20and%20Rebuilding%22%5D%0Aend%0AITI%20--%3E%20Base%0ABase%20--%3E%20Cursor%0ABase%20--%3E%20Pen%0AITI%20--%3E%20Sep%0ATHost%20--%3E%20TR%0ATIC%20--%3E%20TR%0ATP%20--%3E%20TR%0AMW%20--%3E%20TR%0AMW%20--%3E%20THost%0A"})]),fallback:i(()=>e[0]||(e[0]=[l(" Loading... ",-1)])),_:1})),e[7]||(e[7]=t('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>IToolbarItem: The toolbar item contract, defining unique identifiers, display names, descriptions, default hiding rules, separate borders, whether to prevent hiding on drag click, and methods to build views.</li><li>IToolbarHost: The bridge interface between the toolbar and the host (main window), providing access to the main window and view registration/retrieval capabilities.</li><li>ToolbarHost: Implementation of IToolbarHost, holding main window references and maintaining a dictionary to register/find views.</li><li>ToolbarRegistry: The core class for toolbar item registration, discovery, layout assembly, visibility evaluation, and configuration file read/writes.</li><li>ToolbarItemConfig: Configuration models and serialization definitions for rulesets, rule groups, rules, component entries, and layout settings.</li><li>ToolbarImageButtonItemBase: Abstract base class for image button-based toolbar items, unifying icons, labels, click events, and building flows.</li><li>Concrete Toolbar Items: Such as CursorToolItem, PenToolItem, SeparatorToolItem, etc., embodying different features and interactions.</li><li>ToolbarPage: The toolbar configuration page, responsible for CRUD operations on configuration files, layout editing, ruleset editing, and real-time rebuilding.</li><li>MainWindow Initialization and Rebuilding: Responsible for loading default configurations, building toolbars, and updating visibility and highlight states.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The runtime workflow of the Toolbar API is as follows:</p><ul><li>During main window initialization, a ToolbarHost is created and the active configuration is loaded. ToolbarRegistry.Populate is called to inject toolbar items into the root panel.</li><li>ToolbarRegistry discovers all IToolbarItem implementations via reflection, constructing views and applying rulesets to determine initial visibilities.</li><li>After users modify layouts, rulesets, or config files in settings, saving and rebuilding are triggered, and the main window calls RebuildToolbar to re-assemble.</li><li>ToolbarRegistry dynamically evaluates rulesets and updates visibility based on context (annotation mode, PPT mode, user collapsed state).</li></ul>',5)),(o(),s(r,null,{default:i(()=>[a(n,{id:"mermaid-131",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20MW%20as%20%22MainWindow%22%0Aparticipant%20TH%20as%20%22ToolbarHost%22%0Aparticipant%20TR%20as%20%22ToolbarRegistry%22%0Aparticipant%20Root%20as%20%22Root%20Panel%22%0Aparticipant%20TP%20as%20%22Settings%20Page%22%0AMW-%3E%3ETR%20%3A%20EnsureDefaultConfigExists()%0AMW-%3E%3ETH%20%3A%20new%20ToolbarHost(this)%0AMW-%3E%3ETR%20%3A%20LoadActiveConfig()%0AMW-%3E%3ETR%20%3A%20Populate(TH%2C%20Root%2C%20layout)%0ATR-%3E%3ETR%20%3A%20Discover()%20Find%20IToolbarItem%20via%20reflection%0ATR-%3E%3ETR%20%3A%20FlattenEntries()%2FGroupIntoSegments()%0ATR-%3E%3ERoot%20%3A%20Add%20content%20border%2Fseparate%20border%20segment%0ANote%20over%20Root%20%3A%20Apply%20initial%20visibility%20and%20ruleset%0ATP-%3E%3ETR%20%3A%20SaveConfigFile()%2FListConfigFiles()%0ATP-%3E%3EMW%20%3A%20RebuildToolbar()%0AMW-%3E%3ETR%20%3A%20ClearInjected(Root)%0AMW-%3E%3ETR%20%3A%20Populate(TH%2C%20Root%2C%20layout)%0ATR-%3E%3ERoot%20%3A%20Update%20visibility%20UpdateVisibilityByMode(...)%0A"})]),fallback:i(()=>e[1]||(e[1]=[l(" Loading... ",-1)])),_:1})),e[8]||(e[8]=t('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="itoolbaritem-interface-design-specifications" tabindex="-1">IToolbarItem Interface Design Specifications <a class="header-anchor" href="#itoolbaritem-interface-design-specifications" aria-label="Permalink to &quot;IToolbarItem Interface Design Specifications&quot;">​</a></h3><ul><li>Property Definitions <ul><li>Id: Unique identifier for the toolbar item, used to map to concrete implementations and configurations.</li><li>DisplayName/Description: Display names and descriptions, used for UI presentation and help guides.</li><li>DefaultHidingRuleset: Default hiding ruleset, which can be overridden by concrete items.</li><li>DefaultShowSeparateBorder/DefaultPreventHideOnDragClick: Default separate borders and whether to prevent hiding on drag clicks.</li></ul></li><li>View Building <ul><li>BuildView(host): Receives IToolbarHost and returns a WPF FrameworkElement view; events and resources are usually bound here.</li></ul></li><li>Event Handling Mechanisms <ul><li>Unifies binding ButtonMouseUp events via ToolbarImageButtonItemBase, dispatching to OnClick methods of subclasses.</li><li>Subclasses can attach additional host callbacks (such as hooking views to specific main window controls) in AfterBuild.</li></ul></li><li>State Management <ul><li>Default rulesets can be combined via WithHideOnCollapsed/WithPreventHideOnCollapsed, affecting visibility evaluations.</li></ul></li></ul><h3 id="toolbarhost-and-itoolbarhost-services" tabindex="-1">ToolbarHost and IToolbarHost Services <a class="header-anchor" href="#toolbarhost-and-itoolbarhost-services" aria-label="Permalink to &quot;ToolbarHost and IToolbarHost Services&quot;">​</a></h3><ul><li>Capabilities Provided by IToolbarHost <ul><li>Window: Accesses main window instances, facilitating interactions between toolbar items and the main window.</li><li>RegisterView(id, view)/FindView(id): Registers and finds views, supporting cross-component lookups and linkings.</li></ul></li><li>ToolbarHost Implementation Key Points <ul><li>Maintains mappings from IDs to views using dictionaries, avoiding null values and empty string keys.</li><li>Provides coarse-grained access for plugins (which will be narrowed in subsequent phases).</li></ul></li></ul>',5)),(o(),s(r,null,{default:i(()=>[a(n,{id:"mermaid-247",class:"mermaid",graph:"classDiagram%0Aclass%20IToolbarHost%20%7B%0A%2BWindow%0A%2BRegisterView(id%2C%20view)%0A%2BFindView(id)%0A%7D%0Aclass%20ToolbarHost%20%7B%0A-_views%20%3A%20Dictionary%0A%2BWindow%0A%2BRegisterView(id%2C%20view)%0A%2BFindView(id)%0A%7D%0AIToolbarHost%20%3C%7C..%20ToolbarHost%0A"})]),fallback:i(()=>e[2]||(e[2]=[l(" Loading... ",-1)])),_:1})),e[9]||(e[9]=t('<h3 id="toolbarregistry-registration-layout-and-visibility" tabindex="-1">ToolbarRegistry: Registration, Layout, and Visibility <a class="header-anchor" href="#toolbarregistry-registration-layout-and-visibility" aria-label="Permalink to &quot;ToolbarRegistry: Registration, Layout, and Visibility&quot;">​</a></h3><ul><li>Registration and Discovery <ul><li>Discover() scans assemblies via reflection for IToolbarItem implementations on the first call, instantiating and caching them.</li></ul></li><li>Configuration File System <ul><li>Supports listing, loading, saving, and deleting configuration files; automatic backups and rollbacks; default configurations are generated on the first startup.</li></ul></li><li>Layout Assembly <ul><li>Populate() receives layout settings, clears old injected elements, flattens entries into display items, and assembles them into content borders or separate borders by segments.</li><li>Segmenting Algorithm: Forms a separate segment upon encountering separate border tags; otherwise, groups continuous items into the same horizontal StackPanel.</li></ul></li><li>Visibility Evaluation <ul><li>UpdateVisibilityByMode() recursively updates visibility by evaluating rulesets based on annotation modes, PPT modes, and user collapsed states.</li><li>Ruleset Evaluation: Supports And/Or, inversions, empty group handling, and state flags.</li></ul></li></ul>',2)),(o(),s(r,null,{default:i(()=>[a(n,{id:"mermaid-311",class:"mermaid",graph:"flowchart%20TD%0AStart(%5B%22Start%20Populate%22%5D)%20--%3E%20Load%5B%22Load%2FValidate%20layout%22%5D%0ALoad%20--%3E%20Discover%5B%22Discover()%20Find%20IToolbarItem%22%5D%0ADiscover%20--%3E%20Flatten%5B%22FlattenEntries()%20Flatten%20entries%22%5D%0AFlatten%20--%3E%20Group%5B%22GroupIntoSegments()%20Segmenting%22%5D%0AGroup%20--%3E%20Inject%5B%22Inject%20into%20root%20panel%3Cbr%2F%3ESeparate%20border%2FContent%20border%22%5D%0AInject%20--%3E%20Eval%5B%22UpdateVisibilityByMode()%3Cbr%2F%3EEvaluate%20ruleset%22%5D%0AEval%20--%3E%20End(%5B%22Complete%22%5D)%0A"})]),fallback:i(()=>e[3]||(e[3]=[l(" Loading... ",-1)])),_:1})),e[10]||(e[10]=t('<h3 id="itoolbarhost-service-capabilities-add-remove-sort" tabindex="-1">IToolbarHost Service Capabilities (Add/Remove/Sort) <a class="header-anchor" href="#itoolbarhost-service-capabilities-add-remove-sort" aria-label="Permalink to &quot;IToolbarHost Service Capabilities (Add/Remove/Sort)&quot;">​</a></h3><ul><li>Add: Drag IToolbarItem or add ToolbarComponentEntry directly in settings, write to layout and save configuration, then rebuild the toolbar.</li><li>Remove: Remove ToolbarComponentEntry from AddedComponents or child items within groups, save and rebuild.</li><li>Sort: Supports drag-sorting in AddedComponents and child items within groups, rebuilding after saving.</li><li>Rulesets: Rulesets and rules can be configured for each entry to control show/hide logics.</li></ul><h3 id="toolbar-customization-guide" tabindex="-1">Toolbar Customization Guide <a class="header-anchor" href="#toolbar-customization-guide" aria-label="Permalink to &quot;Toolbar Customization Guide&quot;">​</a></h3><ul><li>Creating Custom Toolbar Items <ul><li>Create a new class implementing IToolbarItem or inheriting from ToolbarImageButtonItemBase, setting Id, DisplayName, DefaultHidingRuleset, OnClick, and AfterBuild.</li><li>Examples: CursorToolItem, PenToolItem, SeparatorToolItem.</li></ul></li><li>Configuring Toolbar Layouts <ul><li>Choose available items and drag them to &quot;Added Components&quot; in settings, configuring separate borders, rulesets, and component settings (width, height, font size, opacity, alignment, etc.).</li></ul></li><li>Handling User Interaction Events <ul><li>Invoke corresponding methods on host.Window in OnClick, and hook views to main window controls in AfterBuild.</li></ul></li></ul><h3 id="toolbar-configuration-file-formats-serialization-and-persistence" tabindex="-1">Toolbar Configuration File Formats, Serialization, and Persistence <a class="header-anchor" href="#toolbar-configuration-file-formats-serialization-and-persistence" aria-label="Permalink to &quot;Toolbar Configuration File Formats, Serialization, and Persistence&quot;">​</a></h3><ul><li>File Locations and Naming <ul><li>Configuration Directory: Configs/ToolbarConfigs under the application root path.</li><li>Filenames: Any valid filename (*.json), defaulting to &quot;default&quot;.</li></ul></li><li>Data Models <ul><li>ToolbarLayoutSettings: Contains the components list.</li><li>ToolbarComponentEntry: Contains id, instanceId, hidingRule, hidingRuleset, showSeparateBorder, preventHideOnDragClick, settings, children.</li><li>ToolbarRuleset/ToolbarRuleGroup/ToolbarRule: Supports And/Or, inversions, enabled states, and condition sets.</li></ul></li><li>Serialization and Deserialization <ul><li>Uses Newtonsoft.Json for serialization and deserialization.</li></ul></li><li>Persistence Strategies <ul><li>Copies the main file as a backup before saving, allowing rollbacks on exceptions.</li><li>Supports deletion and resetting to default layouts.</li></ul></li></ul><h3 id="main-window-integration-and-visibility-updates" tabindex="-1">Main Window Integration and Visibility Updates <a class="header-anchor" href="#main-window-integration-and-visibility-updates" aria-label="Permalink to &quot;Main Window Integration and Visibility Updates&quot;">​</a></h3><ul><li>Initialization <ul><li>EnsureDefaultConfigExists(), new ToolbarHost(this), LoadActiveConfig(), Populate(), UpdateToolbarComponentVisibility().</li></ul></li><li>Rebuild <ul><li>ClearInjected() clears old injected elements, and Populate() is called again to refresh highlights and colors.</li></ul></li><li>Visibility <ul><li>UpdateVisibilityByMode() evaluates rulesets based on annotation modes, PPT modes, and user collapsed states.</li></ul></li></ul><h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>Component Coupling <ul><li>An inheritance relationship exists between IToolbarItem and ToolbarImageButtonItemBase, unifying button-based toolbar item building and event handling.</li><li>ToolbarRegistry depends on IToolbarItem discovery and assembly, and on ToolbarItemConfig for ruleset and layout parsing.</li><li>ToolbarPage, as the configuration entry, depends on ToolbarRegistry for file management and layout saving.</li><li>MainWindow, as the host, depends on ToolbarRegistry for assembly and visibility updates.</li></ul></li><li>External Dependencies <ul><li>Newtonsoft.Json for configuration file serialization/deserialization.</li><li>WPF control systems for view building and layouts.</li></ul></li></ul>',10)),(o(),s(r,null,{default:i(()=>[a(n,{id:"mermaid-546",class:"mermaid",graph:"graph%20LR%0AITI%5B%22IToolbarItem%22%5D%20--%3E%20Base%5B%22ToolbarImageButtonItemBase%22%5D%0ABase%20--%3E%20Cursor%5B%22CursorToolItem%22%5D%0ABase%20--%3E%20Pen%5B%22PenToolItem%22%5D%0AITI%20--%3E%20Sep%5B%22SeparatorToolItem%22%5D%0ATHost%5B%22ToolbarHost%22%5D%20--%3E%20TR%5B%22ToolbarRegistry%22%5D%0ATIC%5B%22ToolbarItemConfig%22%5D%20--%3E%20TR%0ATP%5B%22ToolbarPage%22%5D%20--%3E%20TR%0AMW%5B%22MainWindow%22%5D%20--%3E%20TR%0AMW%20--%3E%20THost%0A"})]),fallback:i(()=>e[4]||(e[4]=[l(" Loading... ",-1)])),_:1})),e[11]||(e[11]=t('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Reflection Discovery Cost <ul><li>Discover() performs reflection scans and caches results on the first invocation, avoiding repetitive overhead.</li></ul></li><li>Ruleset Evaluation <ul><li>Ruleset evaluation employs short-circuit logic (And/Or) to reduce unnecessary checks; empty groups and rules compute results directly.</li></ul></li><li>Visibility Updates <ul><li>UpdateVisibilityByMode() recursively traverses injected elements. Keeping the number of injected elements reasonable and avoiding deep nesting is recommended.</li></ul></li><li>Configuration File I/O <ul><li>Backs up before saving and rolls back on failure; saving once after batch modifications is recommended to reduce I/O frequencies.</li></ul></li><li>View Registration <ul><li>ToolbarHost uses dictionaries to store views. Lookup complexity is O(1), but avoid duplicate registrations and empty keys.</li></ul></li></ul><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Toolbar Items Not Displayed <ul><li>Check if DefaultHidingRuleset causes it to be hidden; adjust rulesets or disable rules in settings.</li><li>Verify if Populate() successfully injected elements; logs should contain &quot;Populate complete&quot;.</li></ul></li><li>Configuration File Load Failed <ul><li>Check logs for &quot;config file does not exist/corrupted/backup restored&quot;; verify file existence and JSON structure validity.</li></ul></li><li>Rulesets Ineffective <ul><li>Verify ruleset Mode, IsReversed, and Groups/Rules; check if condition IDs align with context.</li></ul></li><li>View Misalignment After Rebuilding <ul><li>Ensure modifications are saved in settings before rebuilding; check if ClearInjected() cleared old elements.</li></ul></li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The Toolbar API implements pluggable toolbar items, configurable layouts, and programmable visibility controls through clear interfaces and modular designs. Leveraging ToolbarRegistry&#39;s rulesets and configuration systems, users can flexibly customize toolbar appearances and behaviors. With ToolbarHost and ToolbarPage, developers can easily extend new toolbar items and integrate them into the main window. Following existing base classes and ruleset conventions when extending new toolbar items is recommended to ensure a consistent user experience and maintainability.</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><ul><li>Development Specification References: Floating toolbar development specifications and button type lists.</li></ul>',8))])}const w=b(g,[["render",p]]);export{I as __pageData,w as default};
